-- Estructura para la tabla: booking_items
CREATE TABLE IF NOT EXISTS `booking_items` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT ,
    `booking_id` BIGINT UNSIGNED NOT NULL  ,
    `supplier_id` BIGINT UNSIGNED NULL  ,
    `service_type_id` BIGINT UNSIGNED NULL  ,
    `description` VARCHAR(255) NOT NULL  ,
    `currency` VARCHAR(255) NOT NULL  DEFAULT 'USD',
    `exchange_rate` DOUBLE NOT NULL  DEFAULT '1',
    `cost` DOUBLE NOT NULL  DEFAULT '0',
    `sell` DOUBLE NOT NULL  DEFAULT '0',
    `created_at` DATETIME NULL  ,
    `updated_at` DATETIME NULL  ,
    PRIMARY KEY (`id`),
    FOREIGN KEY (`service_type_id`) REFERENCES `service_types` (`id`) ON DELETE set null ON UPDATE no action,
    FOREIGN KEY (`supplier_id`) REFERENCES `suppliers` (`id`) ON DELETE restrict ON UPDATE no action,
    FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE cascade ON UPDATE no action
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

