-- Estructura para la tabla: bookings
CREATE TABLE IF NOT EXISTS `bookings` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT ,
    `lead_id` BIGINT UNSIGNED NULL  ,
    `customer_id` BIGINT UNSIGNED NULL  ,
    `file_number` VARCHAR(255) NOT NULL  ,
    `holder_name` VARCHAR(255) NOT NULL  ,
    `destination` VARCHAR(255) NULL  ,
    `nights` BIGINT UNSIGNED NULL  DEFAULT '0',
    `passengers` BIGINT UNSIGNED NULL  DEFAULT '1',
    `travel_date` DATETIME NULL  ,
    `total_cost` DOUBLE NOT NULL  DEFAULT '0',
    `total_sell` DOUBLE NOT NULL  DEFAULT '0',
    `profit` DOUBLE NOT NULL  DEFAULT '0',
    `status` VARCHAR(255) NOT NULL  DEFAULT 'borrador',
    `currency` VARCHAR(255) NOT NULL  DEFAULT 'USD',
    `exchange_rate` DOUBLE NOT NULL  DEFAULT '1',
    `valid_until` DATETIME NULL  ,
    `internal_notes` TEXT NULL  ,
    `notes` TEXT NULL  ,
    `created_at` DATETIME NULL  ,
    `updated_at` DATETIME NULL  ,
    PRIMARY KEY (`id`),
    FOREIGN KEY (`customer_id`) REFERENCES `users` (`id`) ON DELETE set null ON UPDATE no action,
    FOREIGN KEY (`lead_id`) REFERENCES `leads` (`id`) ON DELETE set null ON UPDATE no action
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

